<?php
require_once "config/db.php";$pageTitle='Membership plans';
if($_SERVER['REQUEST_METHOD']==='POST'){if(($_POST['action']??'')==='add'){ $name=trim($_POST['name']??'');$duration=(int)($_POST['duration_months']??0);$price=$_POST['price']??'';$desc=trim($_POST['description']??'');if(strlen($name)<2||$duration<1||!is_numeric($price)||$price<0){$_SESSION['flash']=['type'=>'error','message'=>'Enter a valid plan.'];}else{try{$st=$pdo->prepare("INSERT INTO plans(name,duration_months,price,description) VALUES(?,?,?,?)");$st->execute([$name,$duration,$price,$desc]);$_SESSION['flash']=['type'=>'success','message'=>'Plan created.'];}catch(PDOException $e){$_SESSION['flash']=['type'=>'error','message'=>'Plan name must be unique.'];}}}elseif(($_POST['action']??'')==='delete'){$st=$pdo->prepare("DELETE FROM plans WHERE id=?");$st->execute([(int)$_POST['id']]);$_SESSION['flash']=['type'=>'success','message'=>'Plan deleted; assigned members are now unassigned.'];}header("Location: plans.php");exit;}
$plans=$pdo->query("SELECT p.*,COUNT(m.id) member_count FROM plans p LEFT JOIN members m ON m.plan_id=p.id GROUP BY p.id ORDER BY p.price")->fetchAll();require "includes/header.php";
?><div class="page-intro"><div><h1>Membership plans</h1><p>Build clear options for every fitness journey.</p></div></div><section class="panel"><div class="panel-head"><div><h3>Create a plan</h3><p>Plan names must be unique.</p></div></div><form method="post" class="form-grid" data-validate><input type="hidden" name="action" value="add"><div class="field"><label>Plan name *</label><input name="name" required minlength="2" placeholder="Premium Plus"></div><div class="field"><label>Duration (months) *</label><input name="duration_months" type="number" min="1" max="60" required></div><div class="field"><label>Price (₹) *</label><input name="price" type="number" min="0" step=".01" required></div><div class="field"><label>Description</label><input name="description" placeholder="What's included?"></div><div class="field field-action"><button class="btn btn-primary">＋ Create plan</button></div></form></section><div class="plan-grid"><?php foreach($plans as $p): ?><article class="plan-card"><div class="plan-top"><span class="plan-glyph">◇</span><span class="status active">AVAILABLE</span></div><h3><?= htmlspecialchars($p['name']) ?></h3><div class="plan-price">₹<?= number_format($p['price']) ?><small> / <?= $p['duration_months'] ?> month(s)</small></div><p><?= htmlspecialchars($p['description']?:'Flexible membership for your fitness goals.') ?></p><div class="plan-meta">♙ <?= $p['member_count'] ?> member(s)</div><form method="post" onsubmit="return confirm('Delete this plan?')"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= $p['id'] ?>"><button class="btn btn-outline full">Delete plan</button></form></article><?php endforeach; ?></div><?php require "includes/footer.php"; ?>